// ОБЩАЯ СХЕМА + ПРОВЕРКА. Одна нода на оба поставщика и на обе попытки.
// Всё детерминированно: LLM ничего здесь не решает.
const CATEGORIES = ['бронирование','оплата','страховка','поломка','продление','жалоба','другое'];
const URGENCY = ['низкая','средняя','высокая'];
const CAT_MAP = {
  'booking':'бронирование','reservation':'бронирование','reserva':'бронирование','аренда':'бронирование',
  'payment':'оплата','billing':'оплата','pago':'оплата','платеж':'оплата','платёж':'оплата','счет':'оплата','счёт':'оплата',
  'insurance':'страховка','франшиза':'страховка','seguro':'страховка',
  'damage':'поломка','breakdown':'поломка','accident':'поломка','дтп':'поломка','авария':'поломка','поломка_и_дтп':'поломка',
  'extension':'продление','продление_аренды':'продление','prolongation':'продление',
  'complaint':'жалоба','claim':'жалоба','queja':'жалоба',
  'other':'другое','otro':'другое','прочее':'другое'
};
const URG_MAP = {'low':'низкая','normal':'средняя','medium':'средняя','high':'высокая','critical':'высокая',
  'urgent':'высокая','низкий':'низкая','средний':'средняя','высокий':'высокая','baja':'низкая','media':'средняя','alta':'высокая'};

const norm = s => String(s ?? '').trim().toLowerCase().replace(/\s+/g,'_');
const toBool = v => typeof v === 'boolean' ? v
  : ['true','yes','да','1','y'].includes(String(v ?? '').trim().toLowerCase());
function mapCat(v){ const n = norm(v); if (CATEGORIES.includes(n)) return n; if (CAT_MAP[n]) return CAT_MAP[n];
  for (const k of Object.keys(CAT_MAP)) if (n.includes(k)) return CAT_MAP[k]; return null; }
function mapUrg(v){ const n = norm(v); return URGENCY.includes(n) ? n : (URG_MAP[n] || null); }
function grabJson(text){
  let t = String(text ?? '').trim().replace(/^```[a-zA-Z]*\s*/,'').replace(/```\s*$/,'').trim();
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a === -1 || b === -1) return null;
  try { return JSON.parse(t.slice(a, b + 1)); } catch(e){ return null; }
}

const item = $input.item.json;

// Контекст заявки: ответ модели не содержит ни request_id, ни эталона — берём из входа.
function ctxFrom(name, minAttempt){
  try {
    const c = $(name).item;
    if (c && c.json && (!minAttempt || Number(c.json.attempt || 1) >= minAttempt)) return c.json;
  } catch(e) {}
  return null;
}
const ctx = ctxFrom('🔁 Переключение на резерв', 2) || ctxFrom('📥 10 обращений') || {};
const base = { ...ctx, ...(item.error !== undefined ? item : {}) };

// Модель берём из СВОЕГО поля маршрута, а не из ответа API:
// своё поле мы задали сами, а ответ может прийти без него или в неожиданном виде.
const raw = String(base.model || item.model || '');
const model = /gigachat/i.test(raw) ? 'gigachat' : (/gpt/i.test(raw) ? 'gpt' : 'unknown');

const common = {
  request_id: base.request_id, expected_category: base.expected_category,
  request_text: base.request_text, attempt: base.attempt || 1,
  model, _t0: base._t0 || 0, _t_end: Date.now(),
  _fallback_from: base._fallback_from || null,
  _fallback_reason: base._fallback_reason || null,
  _fallback_kind: base._fallback_kind || null,
};

// --- ошибка вызова: сеть, 404, 429, таймаут
if (item.error !== undefined) {
  const e = item.error;
  return { json: { ...common,
    category: null, urgency: null, summary: null, needs_human: null, language: null,
    _valid: false, _fail_kind: 'transport',
    _fail_reason: 'Ошибка вызова: ' + String(typeof e === 'string' ? e : (e?.message || JSON.stringify(e))).slice(0,200),
    _fields_filled: 0, _tokens: 0 }};
}

// --- ответ пришёл: приводим к схеме.
// Два возможных формата: сырой ответ API (choices[]) и упрощённый вывод ноды OpenAI (message).
let content = item?.choices?.[0]?.message?.content;
if (content === undefined) content = item?.message?.content;
const u = item?.usage || {};
// нода OpenAI в режиме JSON отдаёт уже разобранный объект — парсить нечего
const p = (content && typeof content === 'object') ? content : grabJson(content);

if (!p) {
  return { json: { ...common,
    category: null, urgency: null, summary: null, needs_human: null, language: null,
    _valid: false, _fail_kind: 'format',
    _fail_reason: 'Модель вернула не JSON: ' + String(content ?? '').slice(0,120),
    _fields_filled: 0, _tokens: Number(u.total_tokens || 0) }};
}

const out = {
  category: mapCat(p.category),
  urgency: mapUrg(p.urgency),
  summary: p.summary ? String(p.summary).trim().slice(0,300) : null,
  needs_human: p.needs_human !== undefined ? toBool(p.needs_human) : null,
  language: p.language ? String(p.language).trim().toLowerCase().slice(0,5) : null,
};

// --- валидация схемы
const errors = [];
if (!out.category) errors.push('category вне схемы');
if (!out.urgency) errors.push('urgency вне схемы');
if (typeof out.needs_human !== 'boolean') errors.push('needs_human не boolean');
if (!out.summary || out.summary.length < 5) errors.push('summary пусто');
if (!out.language) errors.push('language пусто');

return { json: { ...common, ...out,
  _valid: errors.length === 0,
  _fail_kind: errors.length ? 'schema' : null,
  _fail_reason: errors.length ? errors.join('; ') : null,
  _fields_filled: Object.values(out).filter(v => v !== null && v !== '').length,
  _tokens: Number(u.total_tokens || 0) }};

// Переключение на резерв. Причина фиксируется всегда: переключение без причины — потерянный инцидент.
const d = $input.item.json;
// Моделей две, значит резерв — всегда «вторая». Никаких таблиц маршрутизации.
const next = d.model === 'gpt' ? 'gigachat' : 'gpt';

return { json: {
  request_id: d.request_id,
  expected_category: d.expected_category,
  request_text: d.request_text,
  model: next,
  attempt: (d.attempt || 1) + 1,
  _t0: Date.now(),
  _fallback_from: d.model,
  _fallback_kind: d._fail_kind,
  _fallback_reason: d._fail_reason,
  _fallback_at: new Date().toISOString(),
}};

// СРАВНИТЕЛЬНЫЙ ОТЧЁТ. Вся арифметика в коде — ни один показатель не считает LLM.
const cfg = $('⚙️ Настройки').first().json;
const items = $input.all().map(i => i.json);
const PRICE = { gpt: cfg.price_gpt, gigachat: cfg.price_giga };

const stat = {};
const bucket = m => stat[m] = stat[m] || { model: m, calls: 0, valid: 0,
  format_err: 0, transport_err: 0, fields: 0, match: 0, checked: 0, tokens: 0, ms: 0 };

for (const it of items) {
  const m = it._meta;

  // успешная (последняя) попытка
  const b = bucket(m.model);
  b.calls += 1;
  if (m.valid) b.valid += 1;
  if (m.fail_kind === 'format' || m.fail_kind === 'schema') b.format_err += 1;
  if (m.fail_kind === 'transport') b.transport_err += 1;
  b.fields += m.fields_filled; b.tokens += m.tokens; b.ms += (m.ms || 0);
  if (m.category_match !== null) { b.checked += 1; if (m.category_match) b.match += 1; }

  // провалившаяся основная попытка — иначе доля ошибок окажется занижена
  if (m.fallback_from) {
    const f = bucket(m.fallback_from);
    f.calls += 1;
    if (m.fallback_kind === 'transport') f.transport_err += 1; else f.format_err += 1;
    if (m.expected_category) f.checked += 1;
  }
}

const pct = (a, b) => b ? Math.round((a / b) * 1000) / 10 : null;

const по_моделям = Object.values(stat).map(b => ({
  модель: b.model,
  вызовов: b.calls,
  'валидных_%': pct(b.valid, b.calls),
  'полнота_полей_%': pct(b.fields, b.calls * 5),
  'совпадение_категории_%': pct(b.match, b.checked),
  'ошибки_формата_%': pct(b.format_err, b.calls),
  'ошибки_вызова_%': pct(b.transport_err, b.calls),
  'среднее_время_мс': b.calls ? Math.round(b.ms / b.calls) : null,
  токенов: b.tokens,
  'стоимость_руб': Math.round((b.tokens / 1000) * (PRICE[b.model] || 0) * 10000) / 10000,
}));

const fb = items.filter(i => i._meta.fallback_from);

return [{ json: {
  всего_заявок: items.length,
  основная: cfg.primary_model,
  резервная: cfg.fallback_model,
  переключений: fb.length,
  причины: fb.map(i => ({ request_id: i.request_id, из: i._meta.fallback_from, в: i._meta.model,
                          тип: i._meta.fallback_kind, причина: String(i._meta.fallback_reason || '').slice(0,140) })),
  ушло_оператору: items.filter(i => i._meta.degraded).length,
  по_моделям,
  оговорка: 'Тарифы условные, задаются в настройках. Выводы верны только для этого набора из 10 заявок.',
}}];
